{
  "actions": [
    {
      "action": "Separate public seating from private access records",
      "mechanism": "Publish a minimal seating view rather than hiding sensitive columns in a shared spreadsheet.",
      "implementation": "Restrict the source file to designated organizers. Publish attendee identifiers and table/seat assignments only; exclude access flags, notes, and pair requests.",
      "check": "Using an attendee account, inspect the published view, downloads, and linked files; verify no accommodation reasons or private fields are accessible.",
      "risk": "Previously shared copies may persist; revoke their access where possible."
    },
    {
      "action": "Allocate hard requirements before pair preferences",
      "mechanism": "Treat the four clear-route seats as eligible placements for access requirements; optimize pairs only within feasible assignments.",
      "implementation": "Give all 48 seats stable identifiers, mark exactly four as route-qualified, and record access requirements without medical details. Reject conflicting assignments before considering pair preferences.",
      "check": "Test four access requests plus competing pairs: every confirmed access request receives a qualified seat, with no duplicate assignments.",
      "risk": "Incorrect seat eligibility data can invalidate otherwise correct allocations."
    },
    {
      "action": "Protect confirmed accessible placements from automatic changes",
      "mechanism": "A protected-placement flag blocks cancellation cleanup, optimization, and manual reassignment until attendee contact is recorded.",
      "implementation": "Require an organizer to record contact and the resulting arrangement before changing a protected assignment. Preserve the hard requirement whenever attendance continues.",
      "check": "Attempt to move a protected attendee through each editing path; every attempt without recorded contact must fail.",
      "risk": "Sending an unanswered message should not count as completed contact."
    },
    {
      "action": "Process cancellations as atomic seating updates",
      "mechanism": "Versioned updates prevent simultaneous edits from assigning the same vacancy or overwriting protected placements.",
      "implementation": "Route edits through one organizer or controlled form. Validate each proposed change against the latest version, commit it completely, then refresh public assignments and notify affected attendees privately.",
      "check": "Submit two requests for one cancelled seat simultaneously; exactly one succeeds, and protected assignments remain unchanged.",
      "risk": "Direct spreadsheet edits can bypass the update controls."
    },
    {
      "action": "Offer honest choices for late pair requests",
      "mechanism": "A pair preference never authorizes displacement of a hard requirement or a false promise of adjacent seating.",
      "implementation": "When only separated seats remain, privately offer those seats or an optional together-seating waitlist. Retain existing confirmations unless attendees explicitly choose otherwise.",
      "check": "Test a late pair request with only separated vacancies: offer separation, make no adjacent-seat promise, and preserve all confirmed accessible placements.",
      "risk": "Waiting together may mean missing the session."
    },
    {
      "action": "Handle access demand beyond four seats explicitly",
      "mechanism": "A capacity gate prevents organizers from confirming placements that cannot satisfy the required clear route.",
      "implementation": "If all four qualified seats are committed, privately explain the placement limit and offer a timestamped access waitlist. Do not request diagnoses or substitute an unqualified seat.",
      "check": "Submit a fifth access request; verify it receives no unsuitable confirmed placement and displaces no confirmed attendee.",
      "risk": "A waitlist does not guarantee attendance; communicate that clearly."
    },
    {
      "action": "Verify clear routes in the actual room",
      "mechanism": "Physical setup checks ensure spreadsheet eligibility corresponds to usable routes at session time.",
      "implementation": "Label the four qualified seats, keep their routes free of bags and extra chairs, and assign an organizer to inspect before opening and after layout changes.",
      "check": "Inspect all four routes against the required clearance. Introduce a temporary obstruction during rehearsal; staff must detect and remove it before seating.",
      "risk": "Fix obstructions first; do not silently relocate a confirmed attendee."
    }
  ],
  "abstention_reason": ""
}
